var n=`1219-arroz-con-pollo-costa-rican-style`;var t=`world-1219`;var a=`CR`;var o=`central-america-caribbean`;var r=4;var s=51;var c={en:`Arroz con Pollo Costa Rican Style`,ua:`Рис із куркою по-костариканськи`};var l={en:`Arroz con Pollo Costa Rican Style is a dish from Costa Rica featuring chicken thigh, yellow onion, green bell pepper, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Рис із куркою по-костариканськи, страва кухні країни Коста-Рика з такими основними складниками: куряче стегно, жовта цибуля, зелений солодкий перець, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`chicken-thigh`,760,`g`],[`canola-oil`,45,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,150,`g`],[`green-bell-pepper`,140,`g`],[`garlic`,4,`clove`],[`achiote-paste`,28,`g`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 26 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 26 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:26,i:[[`white-rice`,420,`g`],[`chicken-stock`,780,`ml`],[`frozen-green-peas`,150,`g`],[`carrot`,160,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var h={slug:n,id:t,country:`CR`,region:o,servings:4,minutes:51,title:c,text:l,steps:g};export{a as country,h as default,t as id,s as minutes,o as region,r as servings,n as slug,g as steps,l as text,c as title};